const renderToAsset=async opts=>{const c=await svgToCanvas(opts);const img=c.getContext('2d').getImageData(0,0,c.width,c.height);return assetStore.put(await canvasToPngBlob(img))};
const rasterizeLayer=()=>{const l=selected;if(!l)return setToast('Select a layer first.');if(l.type==='raster')return setToast('This is already a paint layer.');if(!l.visible)return setToast('Show the layer before rasterizing it.');if(busyRaster())return;queued(async()=>{const id=await renderToAsset({layerIds:[l.id],background:false,neutralize:l.id});const cur=docRef.current;commit({...cur,layers:cur.layers.map(x=>x.id===l.id?rasterLayerFrom({...l,locked:false},id):x)},'Rasterize Layer')},'Rasterize')};
const mergeDown=()=>{const cur=docRef.current,i=cur.layers.findIndex(x=>x.id===selected?.id);if(i<1)return setToast('Select a layer that has a layer below it.');const top=cur.layers[i],below=cur.layers[i-1];if(!top.visible||!below.visible)return setToast('Both layers must be visible to merge.');if(busyRaster())return;queued(async()=>{const id=await renderToAsset({layerIds:[below.id,top.id],background:false});const c=docRef.current,nl=rasterLayerFrom({name:below.name},id);commit({...c,layers:c.layers.flatMap(x=>x.id===below.id?[nl]:x.id===top.id?[]:[x])},'Merge Down');setIds([nl.id])},'Merge Down')};
const mergeVisible=()=>{const cur=docRef.current,vis=cur.layers.filter(x=>x.visible);if(vis.length<2)return setToast('At least two visible layers are needed.');if(busyRaster())return;queued(async()=>{const id=await renderToAsset({layerIds:vis.map(x=>x.id),background:false});const c=docRef.current,nl=rasterLayerFrom({name:'Merged'},id),first=vis[0].id;commit({...c,layers:c.layers.flatMap(x=>x.id===first?[nl]:x.visible?[]:[x])},'Merge Visible');setIds([nl.id])},'Merge Visible')};
