{devOpen&&<DevelopWorkspace assetStore={assetStore} runOp={(op,buf,params,ctx)=>devClient.run(op,buf,params,ctx)} onClose={()=>setDevOpen(false)} onEditInEditor={editFromDevelop}/>}{xd?.type==='colorSettings'&&<ColorSettingsDialog settings={colorSettings} onCancel={()=>setXd(null)} onApply={v=>{setXd(null);setColorSettings(v);try{localStorage.setItem('zertake.colorSettings',JSON.stringify(v))}catch{}}}/>}{xd?.type==='assign'&&<AssignProfileDialog current={profRef(docProfile)} workingSpace={colorSettings.rgb||SRGB} onCancel={()=>setXd(null)} onApply={assignProfile}/>}{xd?.type==='convert'&&<ConvertProfileDialog current={profRef(docProfile)} defaults={{intent:colorSettings.intent,bpc:colorSettings.bpc}} onCancel={()=>setXd(null)} onApply={convertProfile}/>}{xd?.type==='proofSetup'&&<ProofSetupDialog setup={proof.setup} onCancel={()=>setXd(null)} onApply={st=>{setXd(null);setProof(p=>({...p,setup:st,on:true}))}}/>}{xd?.type==='hdr'&&<HdrToningDialog onCancel={()=>setXd(null)} onApply={applyHdr}/>}{xd?.type==='mode'&&xd.item.value==='Indexed'&&<IndexedColorDialog onCancel={()=>setXd(null)} onApply={applyModeDialog}/>}{xd?.type==='mode'&&xd.item.value==='Bitmap'&&<BitmapDialog onCancel={()=>setXd(null)} onApply={applyModeDialog}/>}{xd?.type==='mode'&&xd.item.value==='Duotone'&&<DuotoneDialog initial={colorOf(doc).duotone} onCancel={()=>setXd(null)} onApply={applyModeDialog}/>}{xd?.type==='selectMask'&&<SelectAndMask image={xd.image} mask={xd.mask} run={(op,buf,params,ctx)=>runInWorker(op,buf,params,ctx)} onCancel={()=>setXd(null)} onApply={applySelectAndMask}/>}{xd?.type==='liquify'&&<LiquifyDialog source={xd.src} onCancel={()=>setXd(null)} onApply={applyLiquify}/>}{xd?.type==='warpText'&&(()=>{const tl=doc.layers.find(x=>x.id===xd.id);return tl?<><div className="dialogBlocker" aria-hidden="true"/><WarpTextDialog layer={tl} onCancel={()=>setXd(null)} onApply={w=>{setXd(null);updateLayer(tl.id,x=>({...x,warp:w}),'Warp Text')}}/></>:null})()}
{crs&&<CameraRaw source={crs.src} initial={crs.initial} offsetX={crs.t.ps.x} offsetY={crs.t.ps.y} run={(op,buf,params,ctx)=>runInWorker(op,buf,params,ctx)} onCancel={()=>{cancelJob();setCrs(null)}} onApply={applyCameraRaw}/>}
{opUi&&<OpDialog key={opUi.op.id+(opUi.initial?'-edit':'')} op={opUi.op} initial={opUi.initial} hist={opUi.hist} busy={opUi.busy} error={opUi.error} preview={opUi.preview} setPreview={setOpPreview} onChange={previewOp} onCancel={cancelOp} onApply={applyOp}/>}
{dialog?.type==='imageSize'&&<ImageSizeDialog doc={doc} onCancel={()=>setDialog(null)} onApply={(w,h,m)=>{setDialog(null);imageSize(w,h,m)}}/>}
